SELECT IIf(Len("" & [directrice])=0,"",Remplacer([F8])),IIf(Len("" & [directrice])=0,"",Trim(Left([directrice],InStr([directrice]," ")-1))),IIf(Len("" & [directrice])=0,"",Mid([directrice],InStr([directrice]," ")+1)),annuaire!code_postal,annuaire![H/F],annuaire!adresse,annuaire!ville,annuaire!téléphone,annuaire!fax,annuaire!magasin FROM [annuaire],[Site] WHERE (((Site.numcli)=1)) 
